const flush = () => new Promise(resolve => setImmediate(resolve));
function context(responses) {
  const requests = [], waits = [];
  const ctx = {MOCK:false, S:{net:{profiles:[]}, info:{}, ap:{ssid:'Loomx'}},
    clamp:(v,a,b)=>Math.min(b,Math.max(a,v)),
    req:async(url,body)=>{requests.push({url,body});const result=responses.shift();if(result instanceof Error) throw result;return result},
    wait:()=>new Promise(resolve=>waits.push(resolve))};
  vm.createContext(ctx);
  vm.runInContext(html.slice(html.indexOf('var wifiScanPromise='),html.indexOf('function busesFrom')),ctx);
  return {ctx,requests,waits};
}
test('one scan polls until completion and repeated presses share it',async()=>{
  const {ctx,requests,waits}=context([{scan:'running',networks:[]},{scan:'running',networks:[]},
    {scan:'complete',networks:[{ssid:'Weak',rssi:-80,enc:0},{ssid:'Secure',rssi:-40,enc:3},
      {ssid:'Secure',rssi:-70,enc:3},{ssid:'',rssi:-30,enc:0}]}]);
  const first=ctx.api.scan();assert.equal(first,ctx.api.scan());
  let done=false;first.then(()=>done=true);
  await flush();assert.equal(done,false);assert.equal(requests.length,1);
  waits.shift()();await flush();assert.equal(done,false);
  waits.shift()();const list=await first;
  assert.deepEqual(JSON.parse(JSON.stringify(list)),[{ssid:'Secure',rssi:-40,lock:true},{ssid:'Weak',rssi:-80,lock:false}]);
  assert.deepEqual(requests.map(r=>r.url),['/json/net?scan=1','/json/net?scan=0','/json/net?scan=0']);
});
test('empty completion stops; failures reject and allow a fresh retry',async()=>{
  for(const response of [{scan:'error',networks:[]},new Error('Offline'),{networks:[]}]){
    const {ctx,requests}=context([response,{scan:'complete',networks:[]}]);
    await assert.rejects(ctx.api.scan());assert.equal(ctx.wifiScanPromise,null);
    assert.equal((await ctx.api.scan()).length,0);assert.equal(requests.length,2);
  }
});
